{
  "root": "main",
  "state": {
    "salesData": [
      { "Month": "Jan", "Orders": 120, "Revenue": 3600, "Ad Spend": 240, "ROAS": 15.0, "RevPerOrder": 30.0 },
      { "Month": "Feb", "Orders": 135, "Revenue": 4050, "Ad Spend": 260, "ROAS": 15.6, "RevPerOrder": 30.0 },
      { "Month": "Mar", "Orders": 98, "Revenue": 2940, "Ad Spend": 180, "ROAS": 16.3, "RevPerOrder": 30.0 },
      { "Month": "Apr", "Orders": 160, "Revenue": 5120, "Ad Spend": 320, "ROAS": 16.0, "RevPerOrder": 32.0 },
      { "Month": "May", "Orders": 175, "Revenue": 5600, "Ad Spend": 340, "ROAS": 16.5, "RevPerOrder": 32.0 },
      { "Month": "Jun", "Orders": 150, "Revenue": 4950, "Ad Spend": 310, "ROAS": 16.0, "RevPerOrder": 33.0 }
    ]
  },
  "elements": {
    "main": { "type": "Stack", "props": { "direction": "vertical", "gap": "md", "padding": 16 }, "children": ["title", "summary", "dataTable", "insights", "nextSteps", "actions", "sources", "footer"] },
    "title": { "type": "Text", "props": { "text": "Home Bakery Sales Snapshot", "variant": "h1" }, "children": [] },
    "summary": { "type": "Text", "props": { "text": "A six-month view shows a clear lift from March to May. Ad spend efficiency should be reviewed by month to optimize performance.", "variant": "body" }, "children": [] },
    "dataTable": { "type": "Table", "props": { "domain": "generic", "preferredPresentation": "table", "statePath": "/salesData", "columns": [{ "key": "Month", "label": "Month" }, { "key": "Orders", "label": "Orders" }, { "key": "Revenue", "label": "Revenue" }, { "key": "Ad Spend", "label": "Ad Spend" }, { "key": "ROAS", "label": "ROAS" }, { "key": "RevPerOrder", "label": "Rev/Order" }] }, "children": [] },
    "insights": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["insightsTitle", "insightsText"] },
    "insightsTitle": { "type": "Text", "props": { "text": "Key Insights", "variant": "h2" }, "children": [] },
    "insightsText": { "type": "Text", "props": { "text": "May was the peak performance month with 16.5x ROAS. Revenue per order has trended upward from 30 to 33 over the period.", "variant": "body" }, "children": [] },
    "nextSteps": { "type": "Stack", "props": { "direction": "vertical", "gap": "sm" }, "children": ["nextStepsTitle", "nextStepsList"] },
    "nextStepsTitle": { "type": "Text", "props": { "text": "Next Quarter Focus", "variant": "h2" }, "children": [] },
    "nextStepsList": { "type": "Text", "props": { "text": "Protect high-efficiency patterns, investigate March softness, test basket size bundles, and set up a monthly dashboard.", "variant": "body" }, "children": [] },
    "actions": { "type": "Stack", "props": { "direction": "horizontal", "gap": "md" }, "children": ["btn1", "btn2"] },
    "btn1": { "type": "Button", "props": { "label": "Data Tools" }, "on": { "press": { "action": "openUrl", "params": { "url": "https://www.datawrapper.de/" } } } },
    "btn2": { "type": "Button", "props": { "label": "Track ROAS" }, "on": { "press": { "action": "openUrl", "params": { "url": "https://support.google.com/google-ads/answer/6297?hl=en" } } } },
    "sources": { "type": "Text", "props": { "text": "Sources: Google Ads, Datawrapper", "variant": "caption" }, "children": [] },
    "footer": { "type": "Divider", "props": {}, "children": [] }
  }
}
